mapper.select:
SELECT fpl.id, fpl.patient_id, p.name AS patient_name, p.gender, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, p.phone, p.id_card, p.medical_record_no, fpl.source, fpl.application_time, fpl.enrollment_time, fpl.primary_doctor, fpl.health_manager, fpl.followup_team, fpl.followup_plan_name, fpl.followup_project, fpl.followup_status, fpl.remark, fpl.created_time FROM followup_patient_list fpl LEFT JOIN patient p ON fpl.patient_id = p.id
AND fpl.patient_id = #{query.patientId}
AND fpl.followup_status = #{query.followupStatus}
AND fpl.primary_doctor LIKE CONCAT('%', #{query.primaryDoctor}, '%')
AND (p.name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR p.phone LIKE CONCAT('%', #{query.searchKeyword}, '%') OR p.medical_record_no LIKE CONCAT('%', #{query.searchKeyword}, '%'))
ORDER BY fpl.created_time DESC
